"""No assistant branding or watermarks in shipped files.

Scans the code, scripts, tests, README and docs for branding phrases.
Paper citations may name model families and the research notes may name
trending repositories (e.g. "claude-mem"), but no file may carry
assistant branding. Standalone "Claude"/"Muse" as a word (not part of a
hyphenated repo name) counts as branding.
"""

import re
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]

# Plain-substring phrases that are never legitimate in shipped files.
BANNED_SUBSTRINGS = [
    "generated by AI",
    "AI-generated",
    "built with AI",
    "as an AI",
    "language model wrote",
]

# Standalone words (not part of a hyphenated repo name) that count as branding.
BANNED_WORDS = [
    re.compile(r"(?<![\w-])Muse(?![\w-])"),
    re.compile(r"(?<![\w-])Claude(?![\w-])"),
    re.compile(r"(?<![\w-])Anthropic(?![\w-])"),
]

SCAN_DIRS = ["src", "scripts", "tests"]
SCAN_FILES = ["README.md", "pyproject.toml"]


def _files():
    for dirname in SCAN_DIRS:
        for path in (ROOT / dirname).rglob("*.py"):
            if path.name == "test_branding.py":
                continue  # the list of banned phrases itself, not shipped prose
            yield path
    for name in SCAN_FILES:
        path = ROOT / name
        if path.exists():
            yield path
    docs = ROOT / "docs"
    if docs.exists():
        yield from docs.rglob("*.md")


def test_no_branding_phrases():
    hits = []
    for path in _files():
        text = path.read_text(errors="ignore")
        for phrase in BANNED_SUBSTRINGS:
            if phrase in text:
                hits.append(f"{path.relative_to(ROOT)}: {phrase!r}")
        for pattern in BANNED_WORDS:
            if pattern.search(text):
                hits.append(f"{path.relative_to(ROOT)}: {pattern.pattern!r}")
    assert not hits, "branding found:\n" + "\n".join(hits)
